namespace BlazorApp.Models;

public class EquipmentItem
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public DateTime LastInspected { get; set; }
}

using BlazorApp.Models;

namespace BlazorApp.Services;

public class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate network/database latency
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new() { Id = 1, Name = "Forklift A",        Location = "Warehouse 1", LastInspected = new DateTime(2026, 6, 10) },
            new() { Id = 2, Name = "Conveyor Belt B",   Location = "Warehouse 2", LastInspected = new DateTime(2026, 5, 22) },
            new() { Id = 3, Name = "Drill Press C",     Location = "Shop Floor",  LastInspected = new DateTime(2026, 4, 15) },
            new() { Id = 4, Name = "Lathe D",           Location = "Shop Floor",  LastInspected = new DateTime(2026, 6, 1)  },
            new() { Id = 5, Name = "Crane E",           Location = "Yard",        LastInspected = new DateTime(2026, 3, 30) },
            new() { Id = 6, Name = "Compressor F",      Location = "Utility Room",LastInspected = new DateTime(2026, 5, 5)  },
            new() { Id = 7, Name = "Welding Rig G",     Location = "Shop Floor",  LastInspected = new DateTime(2026, 6, 20) },
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@attribute [StreamRendering]
@using BlazorApp.Models
@using BlazorApp.Services
@inject EquipmentService EquipmentSvc
@inject PersistentComponentState ApplicationState
@implements IDisposable

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (equipment is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in equipment)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? equipment;
    private PersistingComponentStateSubscription _subscription;

    private const string PersistenceKey = "equipment-inventory";

    protected override async Task OnInitializedAsync()
    {
        // Try to restore data persisted from prerender — avoids a second service call.
        if (ApplicationState.TryTakeFromJson<List<EquipmentItem>>(PersistenceKey, out var restored))
        {
            equipment = restored;
        }
        else
        {
            equipment = await EquipmentSvc.GetEquipmentAsync();
        }

        // During prerender, register a callback to serialize the data into the page HTML
        // so the interactive circuit can pick it up without calling the service again.
        _subscription = ApplicationState.RegisterOnPersisting(() =>
        {
            ApplicationState.PersistAsJson(PersistenceKey, equipment);
            return Task.CompletedTask;
        });
    }

    public void Dispose()
    {
        _subscription.Dispose();
    }
}

